//! Workspace commands in the native menu.
//!
//! The menu never runs a workspace command itself. A custom item emits [`EVENT`] to the focused workspace window with the
//! command id of the JS registry (`desktop/workspace/src/shell/commands.ts`); the workspace shell is the only executor and
//! refuses it while locked. Which ids exist, and the registry's default key for each, is `native-menu.json`, generated by
//! the workspace's `native-menu` test, so a key is written down once. [`accelerator`] is the one place a registry key
//! becomes Tauri accelerator syntax.

use serde::Deserialize;
use serde_json::json;
use tauri::menu::{MenuItem, MenuItemBuilder};
use tauri::{AppHandle, Emitter, Manager, Wry};

/// The event a menu command emits to its window: `{"id": "<registry command id>"}`.
pub const EVENT: &str = "termx-menu-command";

/// Menu item ids that carry a registry command start with this; every other item id is native to the shell.
pub const ITEM_PREFIX: &str = "cmd:";

const MANIFEST: &str = include_str!("../../workspace/src/shell/native-menu.json");

#[derive(Deserialize)]
struct Manifest {
    commands: Vec<Command>,
}

#[derive(Deserialize, Clone, Debug, PartialEq)]
pub struct Command {
    pub id: String,
    #[serde(default)]
    pub keys: Option<String>,
}

pub fn commands() -> Vec<Command> {
    serde_json::from_str::<Manifest>(MANIFEST)
        .map(|manifest| manifest.commands)
        .unwrap_or_default()
}

/// Converts a registry key such as `Mod+Shift+P` or `Ctrl+Shift+\`` to Tauri accelerator syntax (`CmdOrCtrl+Shift+P`,
/// `Ctrl+Shift+Backquote`). Returns `None` for what a menu cannot show: a two-step chord (`Mod+K Z`), an unknown modifier
/// or an unsupported key.
///
/// - `Mod` is Command on macOS and Control elsewhere (`CmdOrCtrl`); `Ctrl` stays Control; `Meta` is Command on macOS and
///   the Windows key elsewhere (`Super`); `Alt` and `Shift` are unchanged.
/// - A letter or digit is upper-cased, `F1` to `F24` are kept, and punctuation is spelled out (`Backquote`, `Comma`,
///   `Backslash`) so it never collides with the `+` separator.
pub fn accelerator(keys: &str) -> Option<String> {
    let keys = keys.trim();
    if keys.is_empty() || keys.split_whitespace().count() != 1 {
        return None;
    }
    let mut parts: Vec<&str> = keys.split('+').collect();
    let key = parts.pop()?;
    let mut out: Vec<String> = Vec::new();
    for modifier in parts {
        out.push(
            match modifier.to_ascii_lowercase().as_str() {
                "mod" => "CmdOrCtrl",
                "ctrl" => "Ctrl",
                "meta" => "Super",
                "alt" => "Alt",
                "shift" => "Shift",
                _ => return None,
            }
            .to_string(),
        );
    }
    out.push(key_name(key)?);
    Some(out.join("+"))
}

fn key_name(key: &str) -> Option<String> {
    let lower = key.to_ascii_lowercase();
    let named = match lower.as_str() {
        "`" => Some("Backquote"),
        "," => Some("Comma"),
        "\\" => Some("Backslash"),
        "tab" => Some("Tab"),
        "escape" => Some("Escape"),
        _ => None,
    };
    if let Some(name) = named {
        return Some(name.to_string());
    }
    let function_key = lower.strip_prefix('f').and_then(|digits| digits.parse::<u8>().ok());
    if matches!(function_key, Some(1..=24)) {
        return Some(lower.to_ascii_uppercase());
    }
    let mut chars = lower.chars();
    match (chars.next(), chars.next()) {
        (Some(letter), None) if letter.is_ascii_alphanumeric() => Some(letter.to_ascii_uppercase().to_string()),
        _ => None,
    }
}

/// A menu item for a registry command. Its accelerator is the registry's default key for it, when the menu can show one.
pub fn command_item(app: &AppHandle, id: &str, label: &str) -> tauri::Result<MenuItem<Wry>> {
    let mut builder = MenuItemBuilder::with_id(format!("{ITEM_PREFIX}{id}"), label);
    let keys = commands()
        .into_iter()
        .find(|command| command.id == id)
        .and_then(|command| command.keys);
    if let Some(accelerator) = keys.as_deref().and_then(accelerator) {
        builder = builder.accelerator(accelerator);
    }
    builder.build(app)
}

/// The registry command id of a menu item, when it is one of ours.
pub fn command_id(item_id: &str) -> Option<&str> {
    let id = item_id.strip_prefix(ITEM_PREFIX)?;
    commands().iter().any(|command| command.id == id).then_some(id)
}

/// Sends the command to the focused workspace window (the main window when none is focused), bringing the main window
/// forward when it was hidden in the tray. The window decides what to do; nothing is executed here.
pub fn emit(app: &AppHandle, id: &str) {
    let focused = app
        .webview_windows()
        .into_iter()
        .find(|(label, window)| {
            (label == "main" || label.starts_with("workspace-")) && window.is_focused().unwrap_or(false)
        })
        .map(|(label, _)| label);
    let target = focused.unwrap_or_else(|| {
        if !crate::ui::main_window_visible(app) {
            crate::ui::show_main_window(app);
        }
        "main".to_string()
    });
    let _ = app.emit_to(target, EVENT, json!({ "id": id }));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn converts_registry_keys_to_tauri_accelerators() {
        let cases = [
            ("Mod+Shift+P", "CmdOrCtrl+Shift+P"),
            ("Mod+P", "CmdOrCtrl+P"),
            ("Mod+,", "CmdOrCtrl+Comma"),
            ("Mod+\\", "CmdOrCtrl+Backslash"),
            ("Ctrl+`", "Ctrl+Backquote"),
            ("Ctrl+Shift+`", "Ctrl+Shift+Backquote"),
            ("Ctrl+Tab", "Ctrl+Tab"),
            ("Ctrl+Shift+Tab", "Ctrl+Shift+Tab"),
            ("Ctrl+Meta+F", "Ctrl+Super+F"),
            ("Ctrl+Shift+G", "Ctrl+Shift+G"),
            ("Mod+Alt+Shift+T", "CmdOrCtrl+Alt+Shift+T"),
            ("Mod+1", "CmdOrCtrl+1"),
            ("F7", "F7"),
            ("Shift+F7", "Shift+F7"),
            ("mod+shift+n", "CmdOrCtrl+Shift+N"),
        ];
        for (keys, expected) in cases {
            assert_eq!(accelerator(keys).as_deref(), Some(expected), "{keys}");
        }
    }

    #[test]
    fn shows_no_accelerator_for_what_a_menu_cannot_express() {
        for keys in ["", "  ", "Mod+K Z", "Mod+K Mod+\\", "Hyper+P", "Mod+", "Mod+F25", "Mod+Home", "Mod+PP"] {
            assert_eq!(accelerator(keys), None, "{keys:?}");
        }
    }

    #[test]
    fn manifest_is_valid_and_has_unique_commands() {
        let all = commands();
        assert!(!all.is_empty(), "native-menu.json did not parse");
        let mut ids: Vec<&str> = all.iter().map(|command| command.id.as_str()).collect();
        ids.sort_unstable();
        let before = ids.len();
        ids.dedup();
        assert_eq!(before, ids.len(), "a command is listed twice");
    }

    #[test]
    fn every_key_in_the_manifest_converts_to_an_accelerator() {
        for command in commands() {
            if let Some(keys) = command.keys {
                assert!(accelerator(&keys).is_some(), "{} has the key {keys}", command.id);
            }
        }
    }

    /// `menu.rs` builds each command with `command_item(app, "<id>", ...)`; those ids, in menu order, are exactly the
    /// manifest. The workspace's `native-menu` test pins the same list from the other side.
    #[test]
    fn menu_builds_exactly_the_manifest_commands_in_order() {
        let source = include_str!("menu.rs");
        let mut built: Vec<String> = Vec::new();
        let mut rest = source;
        while let Some(at) = rest.find("command_item(") {
            rest = &rest[at + "command_item(".len()..];
            let Some(open) = rest.find('"') else { break };
            let after = &rest[open + 1..];
            let Some(close) = after.find('"') else { break };
            built.push(after[..close].to_string());
            rest = &after[close..];
        }
        let manifest: Vec<String> = commands().into_iter().map(|command| command.id).collect();
        assert_eq!(built, manifest);
    }

    #[test]
    fn recognises_only_its_own_item_ids() {
        assert_eq!(command_id("cmd:settings"), Some("settings"));
        assert_eq!(command_id("cmd:rm-rf"), None);
        assert_eq!(command_id("quit"), None);
        assert_eq!(command_id("settings"), None);
    }
}
